import sys

def main():
    import sys
    input = sys.stdin.read().splitlines()
    my_name = input[0]
    n = int(input[1])
    actions = input[2:]

    points = {
        "posted on": 15,
        "commented on": 10,
        "likes": 5
    }

    priority = {}

    for action in actions:
        parts = action.split()
        x = parts[0]
        y = parts[-1][:-2]  # remove 's from the end

        if x == my_name:
            target = y
        elif y == my_name:
            target = x
        else:
            continue

        action_type = " ".join(parts[1:-2])
        if target not in priority:
            priority[target] = 0
        priority[target] += points[action_type]

    # Sort by priority (descending) then by name (ascending)
    sorted_names = sorted(priority.keys(), key=lambda x: (-priority[x], x))

    for name in sorted_names:
        print(name)

main()
